=== FILE: repro/tb_data_byte_order.v ===
// Repro B1: UART data bits must be transmitted least significant bit first.
// Checks only the start bit and the eight data-bit centres of each frame.
`timescale 1ns / 1ps
module tb_uart_frame_tx_repro;
    localparam integer CPB = 4;

    reg        clk   = 1'b0;
    reg        rst   = 1'b1;
    reg        start = 1'b0;
    reg  [7:0] data  = 8'd0;
    wire       tx;
    wire       busy;

    uart_frame_tx #(.CLKS_PER_BIT(CPB)) dut (
        .clk(clk), .rst(rst), .start(start), .data(data), .tx(tx), .busy(busy)
    );

    always #5 clk = ~clk;

    reg [8*64-1:0] nonce;
    integer checks = 0;
    integer failed = 0;
    reg txs [0:63];
    reg bsy [0:63];
    integer n;
    integer k;

    // Drive one start pulse and record tx/busy on the falling edge after each
    // of the 64 rising edges that follow the accepting edge (index 0).
    task send_and_capture(input [7:0] value);
        begin
            @(negedge clk);
            data  = value;
            start = 1'b1;
            @(posedge clk);
            for (n = 0; n < 64; n = n + 1) begin
                @(negedge clk);
                if (n == 0) start = 1'b0;
                txs[n] = tx;
                bsy[n] = busy;
            end
        end
    endtask

    task check_data(input [7:0] value);
        begin
            checks = checks + 1;
            if (txs[CPB/2] !== 1'b0) begin
                failed = failed + 1;
                $display("FAIL data_bits/start_bit data=%h got=%b expected=0", value, txs[CPB/2]);
            end
            for (k = 0; k < 8; k = k + 1) begin
                checks = checks + 1;
                if (txs[CPB*(1+k) + CPB/2] !== value[k]) begin
                    failed = failed + 1;
                    $display("FAIL data_bits/bit_order data=%h bit=%0d got=%b expected=%b",
                             value, k, txs[CPB*(1+k) + CPB/2], value[k]);
                end
            end
        end
    endtask

    initial begin
        if (!$value$plusargs("nonce=%s", nonce)) nonce = "none";
        repeat (3) @(posedge clk);
        @(negedge clk) rst = 1'b0;
        repeat (2) @(posedge clk);

        send_and_capture(8'h01); check_data(8'h01);
        send_and_capture(8'h80); check_data(8'h80);
        send_and_capture(8'h0F); check_data(8'h0F);
        send_and_capture(8'hD2); check_data(8'hD2);

        $display("VERDICT nonce=%0s checks=%0d failed=%0d", nonce, checks, failed);
        $finish;
    end

    initial begin
        #200000;
        $display("TIMEOUT tb_data_byte_order");
        $finish;
    end
endmodule
=== END FILE ===
