// Repro B3: a frame is 11 bit periods (start, 8 data, parity, full stop bit),
// so busy must stay high for exactly 11*CLKS_PER_BIT cycles after a start is
// accepted, then drop. Checks only the busy period.
`timescale 1ns / 1ps
module tb_uart_frame_tx_repro;
    localparam integer CPB = 4;

    reg        clk   = 1'b0;
    reg        rst   = 1'b1;
    reg        start = 1'b0;
    reg  [7:0] data  = 8'd0;
    wire       tx;
    wire       busy;

    uart_frame_tx #(.CLKS_PER_BIT(CPB)) dut (
        .clk(clk), .rst(rst), .start(start), .data(data), .tx(tx), .busy(busy)
    );

    always #5 clk = ~clk;

    reg [8*64-1:0] nonce;
    integer checks = 0;
    integer failed = 0;
    reg txs [0:63];
    reg bsy [0:63];
    integer n;
    integer busy_cycles;
    reg     counting;

    task send_and_capture(input [7:0] value);
        begin
            @(negedge clk);
            data  = value;
            start = 1'b1;
            @(posedge clk);
            for (n = 0; n < 64; n = n + 1) begin
                @(negedge clk);
                if (n == 0) start = 1'b0;
                txs[n] = tx;
                bsy[n] = busy;
            end
        end
    endtask

    task check_period(input [7:0] value);
        begin
            busy_cycles = 0;
            counting    = 1'b1;
            for (n = 0; n < 64; n = n + 1) begin
                if (counting && bsy[n] === 1'b1)
                    busy_cycles = busy_cycles + 1;
                else
                    counting = 1'b0;
            end
            checks = checks + 1;
            if (busy_cycles != 11*CPB) begin
                failed = failed + 1;
                $display("FAIL frame/busy_period data=%h got=%0d expected=%0d",
                         value, busy_cycles, 11*CPB);
            end
        end
    endtask

    initial begin
        if (!$value$plusargs("nonce=%s", nonce)) nonce = "none";
        repeat (3) @(posedge clk);
        @(negedge clk) rst = 1'b0;
        repeat (2) @(posedge clk);

        send_and_capture(8'h55); check_period(8'h55);
        send_and_capture(8'h00); check_period(8'h00);

        $display("VERDICT nonce=%0s checks=%0d failed=%0d", nonce, checks, failed);
        $finish;
    end

    initial begin
        #200000;
        $display("TIMEOUT tb_frame_period");
        $finish;
